SELECT ss.product_id, CASE WHEN ss.revenue >= 3300 THEN 'high' WHEN ss.revenue >= 2000 THEN 'mid' ELSE 'low' END AS revenue_bucket, MAX(i.last_restock) AS last_last_restock FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE i.product_id IN (3, 6, 9) GROUP BY ss.product_id, CASE WHEN ss.revenue >= 3300 THEN 'high' WHEN ss.revenue >= 2000 THEN 'mid' ELSE 'low' END
